input.newString:
import { cacheTag, cacheLife } from 'next/cache'

let products = [
  { id: 1, name: 'Laptop', price: 999, inventory: 45, available: true },
  { id: 2, name: 'Phone', price: 699, inventory: 120, available: true },
  { id: 3, name: 'Tablet', price: 499, inventory: 80, available: true },
  { id: 4, name: 'Headphones', price: 199, inventory: 15, available: true },
  { id: 5, name: 'Watch', price: 299, inventory: 60, available: true },
]

export async function getAllProducts() {
  'use cache'

  cacheTag('products')
  cacheLife('hours')

  await new Promise((resolve) => setTimeout(resolve, 100))
  return products
}

export async function syncProducts() {
  await new Promise((resolve) => setTimeout(resolve, 100))

  products = products.map((product) => {
    const inventoryDelta = Math.floor(Math.random() * 20) - 10
    const newInventory = Math.max(0, product.inventory + inventoryDelta)
    return {
      ...product,
      price: Math.max(1, product.price + (Math.random() > 0.5 ? 5 : -5)),
      inventory: newInventory,
      available: newInventory > 0,
    }
  })

  return products
}

